describe('File Upload Progress Bar', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Adjust the URL to your application's upload page
    });

    it('should display a progress bar for each file being uploaded', () => {
        const fileName = 'example-file.txt'; // Replace with an actual file name
        cy.fixture(fileName).as('fileToUpload');

        cy.get('input[type="file"]').attachFile(this.fileToUpload); // Assuming you have a file input
        cy.get('.upload-button').click(); // Assuming there's a button to start the upload

        cy.get('.progress-bar').should('be.visible'); // Check if the progress bar is visible
        cy.get('.progress-bar').should('have.class', 'uploading'); // Check if the progress bar has the correct class
    });

    it('should not display a progress bar if no file is selected', () => {
        cy.get('.upload-button').click(); // Attempt to upload without selecting a file

        cy.get('.progress-bar').should('not.exist'); // Ensure the progress bar does not exist
    });
});
